//! Synthetic official-shaped receipts, actual native fills and durable Sessions.
//! No account client, actual borrowing or calibrated-profitability claim.
use moloch_replay::{session::Session};
use serde_json::{Value,json};use sha2::{Digest,Sha256};use std::path::PathBuf;
const T:&str="11111111-1111-4111-8111-111111111111";
const P:&str="22222222-2222-4222-8222-222222222222";
const R:&str="33333333-3333-4333-8333-333333333333";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn receipt(endpoint:String,data:Value,start:i64,end:i64)->Value{json!({"endpoint":endpoint,"status":200,"requestStartedAt":iso(start),"receivedAt":iso(end),"data":data})}
fn snapshot(cash:Value,debt:Value,available:Value,power:Value,at:i64)->Value{json!({
 "account":receipt(format!("/account?tournamentId={T}"),json!({"id":P,"balance":cash,"availableAdvance":available,"buyingPower":power}),at,at+1),
 "collateral":receipt(format!("/portfolio/collateral?tournamentId={T}"),json!({"availableAdvance":available,"data":[{"profileId":P,"tournamentId":T,"componentId":"own-101","coveredExchangeIds":[101],"relationshipIds":[R],"outstandingAdvance":if debt==json!(0.4){json!(0.2)}else{json!(0)},"guaranteedPayoutFloor":1,"diagnostic":null},{"profileId":P,"tournamentId":T,"componentId":"own-102","coveredExchangeIds":[102],"relationshipIds":[R],"outstandingAdvance":if debt==json!(0.4){json!(0.2)}else{json!(0)},"guaranteedPayoutFloor":1,"diagnostic":null}]}),at+2,at+3)})}
struct F{root:PathBuf,bank:Session,policy:Value,seed:Value,before:Value,seq:u64}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{let root=std::env::temp_dir().join(format!("live-collateral-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let policy=json!({"quantity":2,"maximumMarkets":3,"entryStopAt":iso(100_000)});let seed=json!({"runId":"collateral-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let mut bank=Session::open_live(&root,&policy,&seed).unwrap();
  for(i,ex)in ["101","102"].iter().enumerate(){let at=iso(i as i64*2500);bank.accept("books",i as u64+1,&json!({"type":"book","receivedAt":at,"book":{"tournamentId":T,"marketId":ex,"exchangeId":ex,"sequence":"1","sourceAt":at,"requestStartedAt":at,"receivedAt":at,"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}})).unwrap();}
  assert_eq!(bank.engine().order_records().len(),4);Self{root,bank,policy,seed,before:snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1),seq:0}
 }
 fn event(&self,kind:&str,id:&str,after:Value,at:i64)->Value{let pending:Vec<_>=self.bank.engine().order_records().iter().filter(|q|q["retired"]==false).map(|q|q["id"].clone()).collect();json!({"type":kind,"source":"official_sig_api_v1","eventId":id,"receivedAt":iso(at),"processedAt":iso(at),"bankScope":{"runId":"collateral-fixture","bankManifestHash":self.bank.manifest_hash(),"tournamentId":T,"tournamentSlug":"cup","profileId":P},"expectedReportHash":hash(&self.bank.engine().report().unwrap()),"boundary":{"nativeHead":self.bank.durable_head(),"ordinaryDispatchHash":"b".repeat(64),"packageDispatchHash":"c".repeat(64),"queueHeadHash":"d".repeat(64),"ownerLeaseHash":"e".repeat(64),"unknownCount":0,"activeRequest":null,"unsubmittedOrderIds":pending},"before":self.before,"after":after})}
 fn accept(&mut self,e:&Value){self.seq+=1;self.bank.accept("collateral-owner",self.seq,e).unwrap();}
 fn baseline(&mut self){let e=self.event("actual_collateral_baseline","baseline",self.before.clone(),3000);self.accept(&e);}
 fn actual(&mut self,side:&str,at:i64)->Vec<Value>{let qs:Vec<_>=self.bank.engine().order_records().into_iter().filter(|q|q["side"]==side&&q["retired"]==false&&q["action"]=="buy").collect();assert_eq!(qs.len(),2);for q in &qs{let e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"f".repeat(64),"orderId":q["id"],"actualOrderId":format!("90{}",q["id"].as_u64().unwrap()),"marketId":q["marketId"],"exchangeId":q["exchangeId"],"side":q["side"],"action":"buy","quantity":2,"price":q["price"],"receivedAt":iso(at+500)});let n=self.bank.last_source_sequence("actual")+1;self.bank.accept("actual",n,&e).unwrap();}
  for q in &qs{let e=json!({"type":"actual_fill","source":"official_sig_api_v1","receiptHash":"a".repeat(64),"orderId":q["id"],"actualOrderId":format!("90{}",q["id"].as_u64().unwrap()),"fillId":format!("80{}",q["id"].as_u64().unwrap()),"marketId":q["marketId"],"exchangeId":q["exchangeId"],"side":q["side"],"action":"buy","quantity":2,"price":q["price"],"fee":"0.000000","executedAt":iso(at),"receivedAt":iso(at+600)});let n=self.bank.last_source_sequence("actual")+1;self.bank.accept("actual",n,&e).unwrap();}qs
 }
 fn ack(&self,qs:&[Value],borrow:bool,start:i64,end:i64)->Value{let rows:Vec<_>=qs.iter().enumerate().map(|(i,q)|{let no=q["side"]=="NO";json!({"index":i,"data":{"orderId":format!("90{}",q["id"].as_u64().unwrap()),"exchangeId":q["exchangeId"],"side":if no{"no"}else{"yes"},"action":"buy","quantity":2,"price":if no{0.55}else{0.4},"totalCost":if no{1.1}else{0.8},"all":{"fullNotionalCost":if no{1.1}else{0.8},"effectiveEntryCost":if borrow{0.6}else{1.1},"collateralSavings":if borrow{0.2}else{0.0},"collateralRepayment":if borrow{0.0}else{0.2},"redemptionCredit":if borrow{0}else{2},"netBuyingPowerImpact":if borrow{0.8}else{-0.9},"relationshipIds":[R],"componentId":format!("own-{}",q["exchangeId"].as_str().unwrap()),"guaranteedPayoutFloorAfter":1,"outstandingAdvanceAfter":if borrow{json!(0.2)}else{json!(0)}}}})}).collect();receipt("/orders/multi-leg".into(),json!({"results":rows}),start,end)}
 fn borrowed(&mut self){self.baseline();let qs=self.actual("YES",6000);let after=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);let mut e=self.event("actual_collateral_execution","borrow",after.clone(),7100);e["receipts"]=json!([self.ack(&qs,true,5000,6500)]);self.accept(&e);self.before=after;}
 fn denied(&mut self,e:&Value){let report=self.bank.engine().report().unwrap();let orders=self.bank.engine().order_records();let head=self.bank.durable_head();assert!(self.bank.accept("collateral-owner",self.seq+1,e).is_err());assert_eq!(self.bank.engine().report().unwrap(),report);assert_eq!(self.bank.engine().order_records(),orders);assert_eq!(self.bank.durable_head(),head);}
}
#[test]fn actual_borrow_is_debt_and_never_wallet_profit_or_sizing_cash(){let mut f=F::new();f.borrowed();let r=f.bank.engine().report().unwrap();assert_eq!(r["cash"],"998.400000");assert_eq!(r["realized"],"0.000000");assert_eq!(r["ownedCost"],"1.600000");let c=&r["collateralAccounting"];assert_eq!(c["officialCash"],"998.800000");assert_eq!(c["officialDebt"],"0.400000");assert_eq!(c["collateralCashAdjustment"],"0.400000");assert_eq!(c["availableAdvanceAdmittedForSizing"],"0.000000");assert_eq!(c["netCashAfterDebt"],"998.400000");}
#[test]fn repayment_and_native_pair_redemption_are_not_double_credited(){let mut f=F::new();f.borrowed();let qs=f.actual("NO",8000);let after=snapshot(json!(1000.2),json!(0),json!(0.5),json!(1000.7),9000);let mut e=f.event("actual_collateral_execution","repay",after,9100);e["receipts"]=json!([f.ack(&qs,false,7500,8500)]);f.accept(&e);let r=f.bank.engine().report().unwrap();assert_eq!(r["cash"],"1000.200000");assert_eq!(r["realized"],"0.200000");assert_eq!(r["ownedCost"],"0.000000");assert_eq!(r["collateralAccounting"]["officialDebt"],"0.000000");assert_eq!(r["collateralAccounting"]["cumulativeRepaid"],"0.400000");assert_eq!(r["collateralAccounting"]["officialCash"],"1000.200000");assert_eq!(f.bank.engine().fills().len(),4);}
fn settlement(f:&F)->Value{let after=snapshot(json!(1000.4),json!(0),json!(0),json!(1000.4),9000);let mut e=f.event("actual_collateral_settlement","settled",after,9100);let rows:Vec<_>=[("101","win",2),("102","loss",0)].iter().map(|(ex,kind,payout)|json!({"id":format!("engine-{ex}"),"type":kind,"createdAt":iso(8000),"exchangeId":ex,"marketId":ex,"settlementOption":"YES","settlementOutcome":null,"shares":2,"avgEntryPrice":null,"costBasis":null,"payout":payout,"realizedPnl":null})).collect();e["settlements"]=receipt("/tournaments/cup/portfolio/settlements?limit=200".into(),json!({"data":rows,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null}}),8100,8200);e["settlementIds"]=json!(["engine-101","engine-102"]);e}
#[test]fn official_zero_and_full_settlements_consume_lots_without_synthetic_fills(){let mut f=F::new();f.borrowed();let e=settlement(&f);f.accept(&e);let r=f.bank.engine().report().unwrap();assert_eq!(r["cash"],"1000.400000");assert_eq!(r["realized"],"0.400000");assert_eq!(r["ownedCost"],"0.000000");assert_eq!(r["collateralAccounting"]["actualSettlements"],2);assert_eq!(r["collateralAccounting"]["officialDebt"],"0.000000");assert_eq!(f.bank.engine().fills().len(),2);let expected=r;let orders=f.bank.engine().order_records();let scratch=f.root.join("placeholder");let blank=Session::open_live(&scratch,&f.policy,&f.seed).unwrap();let old=std::mem::replace(&mut f.bank,blank);drop(old);f.bank=Session::open_live(&f.root,&f.policy,&f.seed).unwrap();assert_eq!(f.bank.engine().report().unwrap(),expected);assert_eq!(f.bank.engine().order_records(),orders);}
#[test]fn uncertain_or_incomplete_settlement_never_removes_positions(){for case in ["side","quantity","coverage","cash","correction","foreign"]{let mut f=F::new();f.borrowed();let mut e=settlement(&f);match case{"side"=>e["settlements"]["data"]["data"][0]["settlementOption"]=Value::Null,"quantity"=>e["settlements"]["data"]["data"][0]["shares"]=Value::Null,"coverage"=>e["settlements"]["data"]["coverage"]["complete"]=json!(false),"cash"=>e["after"]["account"]["data"]["balance"]=json!(1001),"correction"=>e["settlements"]["data"]["data"][0]["type"]=json!("correction"),_=>e["settlements"]["endpoint"]=json!("/portfolio/settlements?limit=200")};f.denied(&e);}}
#[test]fn session_scope_head_unknown_and_stale_report_reject_before_durability(){for case in ["head","run","manifest","unknown","report","active"]{let mut f=F::new();let mut e=f.event("actual_collateral_baseline","baseline",f.before.clone(),3000);match case{"head"=>e["boundary"]["nativeHead"]["sequence"]=json!(999),"run"=>e["bankScope"]["runId"]=json!("other"),"manifest"=>e["bankScope"]["bankManifestHash"]=json!("0".repeat(64)),"unknown"=>e["boundary"]["unknownCount"]=json!(1),"report"=>e["expectedReportHash"]=json!("0".repeat(64)),_=>e["boundary"]["activeRequest"]=json!("request")};f.denied(&e);}}
#[test]fn actual_fill_coverage_and_cash_equations_cannot_be_replaced_by_ack_totals(){for case in ["missing","notional","debt","cash","power","clock"]{let mut f=F::new();f.baseline();let qs=f.actual("YES",6000);let after=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);let mut e=f.event("actual_collateral_execution","borrow",after,7100);e["receipts"]=json!([f.ack(&qs,true,5000,6500)]);match case{"missing"=>{e["receipts"][0]["data"]["results"].as_array_mut().unwrap().pop();},"notional"=>e["receipts"][0]["data"]["results"][0]["data"]["all"]["fullNotionalCost"]=json!(0.7),"debt"=>e["after"]["collateral"]["data"]["data"][0]["outstandingAdvance"]=json!(0.5),"cash"=>e["after"]["account"]["data"]["balance"]=json!(1000),"power"=>e["receipts"][0]["data"]["results"][0]["data"]["all"]["netBuyingPowerImpact"]=json!(0),_=>e["receipts"][0]["receivedAt"]=json!(iso(5900))};f.denied(&e);}}

#[test]fn opening_official_cash_cannot_rebase_seeded_bank_and_committed_refs_are_exact(){
 let mut f=F::new();let mut e=f.event("actual_collateral_baseline","baseline",f.before.clone(),3000);
 e["after"]["account"]["data"]["balance"]=json!(1001);e["after"]["account"]["data"]["buyingPower"]=json!(1001.5);f.denied(&e);
 let e=f.event("actual_collateral_baseline","baseline",f.before.clone(),3000);f.accept(&e);
 assert_eq!(f.bank.committed_source_hash("collateral-owner",1),Some(hash(&e).as_str()));
 assert_eq!(f.bank.committed_source_hash("collateral-owner",2),None);
 let report=f.bank.engine().report().unwrap();assert!(!f.bank.accept("collateral-owner",1,&e).unwrap());assert_eq!(f.bank.engine().report().unwrap(),report);
 let mut changed=e.clone();changed["eventId"]=json!("tampered");assert!(f.bank.accept("collateral-owner",1,&changed).is_err());
}

#[test]fn cross_group_advance_is_aggregate_not_misattributed_to_unlinked_traded_group(){
 let mut f=F::new();for(index,row)in f.before["collateral"]["data"]["data"].as_array_mut().unwrap().iter_mut().enumerate(){row["coveredExchangeIds"]=json!([150+index]);}
 f.baseline();let qs=f.actual("YES",6000);let mut after=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);for(index,row)in after["collateral"]["data"]["data"].as_array_mut().unwrap().iter_mut().enumerate(){row["coveredExchangeIds"]=json!([150+index]);}
 let mut ack=f.ack(&qs,true,5000,6500);for row in ack["data"]["results"].as_array_mut().unwrap(){row["data"]["all"]["componentId"]=Value::Null;row["data"]["all"]["relationshipIds"]=json!([]);row["data"]["all"]["guaranteedPayoutFloorAfter"]=json!(0);row["data"]["all"]["outstandingAdvanceAfter"]=json!(0);}
 let mut e=f.event("actual_collateral_execution","cross-group",after,7100);e["receipts"]=json!([ack]);f.accept(&e);let c=f.bank.engine().collateral_report().unwrap();assert_eq!(c["officialDebt"],"0.400000");assert_eq!(c["componentStates"]["own-101"]["outstandingAdvance"],json!(0.2));assert_eq!(f.bank.engine().report().unwrap()["realized"],"0.000000");
}
